shell_commands:
git show origin/main:package-lock.json > /tmp/main-lock.json; git show HEAD:package-lock.json > /tmp/head-lock.json; python3 - <<'EOF'
import json
for f in ('/tmp/main-lock.json','/tmp/head-lock.json'):
    d=json.load(open(f))
    for k in d['packages']:
        if 'vertexai' in k and k.count('node_modules')==1:
            print(f, k, d['packages'][k].get('version'))
    print('---')
EOF
